scripts.divide_and_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Divide each A_i by B_i, keeping only whole-number part, then sum
    total = sum(int(a // b) for a, b in zip(A, B))

    return float(total)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count pairs (i, j) where i < j and values[i] > values[j]
    count = 0
    n = len(values)
    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.lcg_generator:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    # Apply the recurrence k times
    for _ in range(k):
        s = (a * s + b) % m

    return float(s)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod 'mod'
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

